/* WCCAS Copy of Grades
   Data is saved in this browser's localStorage (the "database").
   Use "Backup data" / "Restore data" to move records between computers. */

// Fixed staff log-ins (no sign-up). The School Administrator can change any of these passwords.
const FIXED = {
  registrar: { user: 'collegeregistraradmin', pass: 'collegeregistrarwccas2014', label: 'College Registrar' },
  jshs: { user: 'jshsregistraradmin', pass: 'shsregistrarwccas2014', label: 'JSHS Registrar' },
  finance: { user: 'financeadmin', pass: 'financewccas2014', label: 'Finance' },
  admin: { user: 'superadmin', pass: 'superadminwccas2014', label: 'School Administrator' }
};
const KEY = 'wccas_db_v1';
const SCHOOL = 'West Central College of Arts and Science Inc.';
const LOGO = 'data:image/jpeg;base64,'; // embedded copy of wccas.jpg so it is stored in the database and in generated documents

const SEMS = ['First Semester', 'Summer Class', 'Second Semester'];
const SEM_ORDER = { 'First Semester': 1, 'Second Semester': 2, 'Summer Class': 3 };
const LEVELS = ['First Year College', 'Second Year College', 'Third Year College', 'Fourth Year College'];
const SYS = [];
for (let y = 2014; y <= 2029; y++) SYS.push('S.Y. ' + y + '-' + (y + 1));

const $ = id => document.getElementById(id);
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

/* ---------- database ---------- */
let db = loadDB();
db.accounts = db.accounts || []; // faculty and student log-ins (passwords stored as salted hashes)
db.settings = db.settings || { facultySignup: true };
db.creds = db.creds || {}; // password overrides for the fixed staff log-ins
db.enrollments = db.enrollments || [];

function seed() {
  return {
    meta: { school: SCHOOL, logo: LOGO, created: new Date().toISOString() },
    students: [{ id: '2024-0001', name: 'Juan Dela Cruz', course: 'Bachelor of Science in Information Technology', yearGraduated: '' }],
    terms: [{
      tid: 't' + Date.now(), studentNo: '2024-0001', sy: 'S.Y. 2024-2025', sem: 'First Semester',
      level: 'First Year College', section: 'BSIT 1-A',
      subjects: [
        { code: 'GE 101', desc: 'Understanding the Self', units: 3, grade: '1.50' },
        { code: 'GE 102', desc: 'Readings in Philippine History', units: 3, grade: '1.75' },
        { code: 'IT 101', desc: 'Introduction to Computing', units: 3, grade: '1.25' }
      ]
    }]
  };
}
function loadDB() {
  try {
    const d = JSON.parse(localStorage.getItem(KEY));
    if (d && Array.isArray(d.students) && Array.isArray(d.terms)) return d;
  } catch (e) { /* fall through */ }
  const d = seed();
  localStorage.setItem(KEY, JSON.stringify(d));
  return d;
}
function save() {
  db.meta = db.meta || {};
  db.meta.school = SCHOOL;
  db.meta.logo = LOGO;
  db.meta.updated = new Date().toISOString();
  try { localStorage.setItem(KEY, JSON.stringify(db)); }
  catch (e) { alert('Could not save. Browser storage is full or blocked.'); }
}
const student = no => db.students.find(s => s.id === no);
const termsOf = no => db.terms.filter(t => t.studentNo === no).sort(termSort);
function termSort(a, b) { return a.sy.localeCompare(b.sy) || (SEM_ORDER[a.sem] || 9) - (SEM_ORDER[b.sem] || 9); }

/* ---------- grades ---------- */
function normGrade(v) {
  v = String(v || '').trim().toUpperCase();
  if (!v) return '';
  const n = parseFloat(v);
  if (!isNaN(n) && /^[0-9.]+$/.test(v)) return n.toFixed(2);
  return v; // INC, DRP, W, UD ...
}
function remark(g) {
  g = String(g || '').toUpperCase();
  if (!g) return '';
  if (g === 'INC') return 'Incomplete';
  if (g === 'DRP') return 'Dropped';
  if (g === 'W') return 'Withdrawn';
  if (g === 'UD') return 'Unofficially Dropped';
  const n = parseFloat(g);
  if (isNaN(n)) return '';
  return n <= 3 ? 'Passed' : 'Failed';
}
const remarkClass = g => { const r = remark(g); return r === 'Passed' ? 'pass' : (r === 'Failed' ? 'fail' : ''); };
function gwa(subjects) {
  let pts = 0, units = 0;
  subjects.forEach(s => {
    const g = parseFloat(s.grade), u = parseFloat(s.units);
    if (!isNaN(g) && g >= 1 && g <= 5 && u > 0) { pts += g * u; units += u; }
  });
  return units ? (pts / units).toFixed(2) : '';
}
const totalUnits = subjects => subjects.reduce((a, s) => a + (parseFloat(s.units) || 0), 0);

/* ---------- login & sign-up ---------- */
let session = null; // { role: 'registrar' | 'faculty' | 'student', user, studentNo }
const ROLE_LABEL = { registrar: 'College Registrar', jshs: 'JSHS Registrar', admin: 'School Administrator', faculty: 'Faculty', student: 'Student', finance: 'Finance' };
const isAdmin = () => !!session && session.role === 'admin';
const isJshs = () => !!session && session.role === 'jshs';
const isReg = () => !!session && (session.role === 'registrar' || session.role === 'admin'); // college registrar powers
function myDivisions() {
  if (!session) return [];
  if (session.role === 'admin') return ['jhs', 'shs', 'college'];
  if (session.role === 'registrar') return ['college'];
  if (session.role === 'jshs') return ['jhs', 'shs'];
  return [];
}
const canEnr = d => myDivisions().includes(d);

function showApp() {
  $('login').classList.add('hidden');
  $('app').classList.remove('hidden');
}
function randSalt() {
  const a = new Uint8Array(8);
  if (window.crypto && crypto.getRandomValues) crypto.getRandomValues(a);
  else for (let i = 0; i < a.length; i++) a[i] = Math.floor(Math.random() * 256);
  return Array.from(a).map(x => x.toString(16).padStart(2, '0')).join('');
}
async function hashPw(pw, salt, forceSimple) {
  const data = salt + '|' + pw;
  if (!forceSimple && window.crypto && crypto.subtle) {
    const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(data));
    return 'sha:' + Array.from(new Uint8Array(buf)).map(x => x.toString(16).padStart(2, '0')).join('');
  }
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57; // fallback when the browser has no crypto.subtle
  for (let i = 0; i < data.length; i++) { const ch = data.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return 'c53:' + (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}
async function checkFixed(role, pw) {
  const o = db.creds[role];
  if (o) return (await hashPw(pw, o.salt, o.hash.startsWith('c53:'))) === o.hash;
  return pw === FIXED[role].pass;
}
async function verifyCurrentPassword(pw) {
  return !!session && !!FIXED[session.role] && checkFixed(session.role, pw);
}
function startSession(sess) {
  session = sess;
  sessionStorage.setItem('wccas_auth', JSON.stringify(sess));
  document.body.dataset.role = sess.role;
  $('who').textContent = ROLE_LABEL[sess.role] + ': ' + sess.user;
  $('loginErr').textContent = ''; $('loginOk').textContent = ''; $('pass').value = '';
  showApp();
  setupEnroll();
  setupRegName();
  setupFinName();
  if (sess.role === 'student') { doSearch(); return; }
  if (sess.role === 'jshs') return;
  populateCourses();
  $('results').innerHTML = '<p class="empty-state">Search by student number, or leave the boxes blank to list every record.</p>';
  $('barcode').focus();
}
$('loginForm').addEventListener('submit', async e => {
  e.preventDefault();
  const u = $('user').value.trim(), p = $('pass').value;
  for (const role of Object.keys(FIXED)) {
    if (u === FIXED[role].user && await checkFixed(role, p)) { startSession({ role, user: u }); return; }
  }
  const acc = db.accounts.find(x => x.user.toLowerCase() === u.toLowerCase());
  if (acc && await hashPw(p, acc.salt, acc.hash.startsWith('c53:')) === acc.hash) {
    startSession({ role: acc.role, user: acc.user, studentNo: acc.studentNo });
    return;
  }
  $('loginOk').textContent = '';
  $('loginErr').textContent = 'Wrong username or password. Check both and try again.';
});
$('btnLogout').addEventListener('click', () => {
  sessionStorage.removeItem('wccas_auth');
  location.reload(); // back to the home (log in) page
});

let signupRole = 'faculty';
function openSignup(role) {
  if (role === 'faculty' && !facultySignupOpen()) return;
  signupRole = role;
  $('suTitle').textContent = (role === 'faculty' ? 'Faculty' : 'Student') + ' sign up';
  $('suNote').textContent = role === 'faculty'
    ? 'Create the username and password you will use to log in. Faculty can enter grades but cannot edit, delete or print them.'
    : 'Your username must be your Student No./LRN exactly as the Registrar recorded it. Student access is view-only.';
  $('suErr').textContent = ''; $('suUser').value = ''; $('suPass').value = '';
  $('loginForm').classList.add('hidden');
  $('signupForm').classList.remove('hidden');
  $('suUser').focus();
}
function backToLogin(msg) {
  $('signupForm').classList.add('hidden');
  $('loginForm').classList.remove('hidden');
  $('loginOk').textContent = msg || '';
  $('loginErr').textContent = '';
  $('user').focus();
}
$('btnFaculty').addEventListener('click', () => openSignup('faculty'));
$('btnStudent').addEventListener('click', () => openSignup('student'));
$('suBack').addEventListener('click', () => backToLogin());
$('signupForm').addEventListener('submit', async e => {
  e.preventDefault();
  const u = $('suUser').value.trim(), p = $('suPass').value, err = $('suErr');
  if (signupRole === 'faculty' && !facultySignupOpen()) { err.textContent = 'Faculty sign-up is closed. Ask the Registrar.'; return; }
  if (u.length < 3 || /\s/.test(u)) { err.textContent = 'Username must be at least 3 characters with no spaces.'; return; }
  if (p.length < 6) { err.textContent = 'Password must be at least 6 characters.'; return; }
  if (Object.keys(FIXED).some(r => FIXED[r].user.toLowerCase() === u.toLowerCase()) || db.accounts.some(x => x.user.toLowerCase() === u.toLowerCase())) {
    err.textContent = 'That username is already taken. Choose another.'; return;
  }
  let studentNo;
  if (signupRole === 'student') {
    const st = db.students.find(x => x.id.toLowerCase() === u.toLowerCase());
    if (!st) { err.textContent = 'No student record has the Student No./LRN "' + u + '". Ask the Registrar to add you first.'; return; }
    studentNo = st.id;
  }
  const salt = randSalt();
  db.accounts.push({ user: u, role: signupRole, salt, hash: await hashPw(p, salt), studentNo, created: new Date().toISOString() });
  save();
  backToLogin('Account created. Log in with your new username and password.');
});

/* ---------- live clock ---------- */
function tick() {
  const d = new Date();
  $('clock').textContent = d.toLocaleDateString('en-PH', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }) +
    ' | ' + d.toLocaleTimeString('en-PH', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
}
tick();
setInterval(tick, 1000);

/* ---------- dropdowns ---------- */
function opts(list, selected, blank) {
  return (blank ? '<option value="">' + esc(blank) + '</option>' : '') +
    list.map(v => '<option' + (v === selected ? ' selected' : '') + '>' + esc(v) + '</option>').join('');
}
$('sy').innerHTML = opts(SYS, '', 'All school years');
$('sem').innerHTML = opts(SEMS, '', 'All semesters');
$('lvl').innerHTML = opts(LEVELS, '', 'All grade levels');

/* ---------- modal ---------- */
function openModal(title, html, wide) {
  $('modalBody').oninput = null; $('modalBody').onclick = null; clearInterval(enrTimer);
  $('modalTitle').textContent = title;
  $('modalBody').innerHTML = html;
  $('modalBox').classList.toggle('wide', !!wide);
  $('modal').classList.remove('hidden');
  const f = $('modalBody').querySelector('input,select');
  if (f) f.focus();
}
function closeModal() { $('modal').classList.add('hidden'); $('modalBody').innerHTML = ''; $('modalBody').oninput = null; $('modalBody').onclick = null; clearInterval(enrTimer); }
$('modalClose').addEventListener('click', closeModal);
document.addEventListener('keydown', e => { if (e.key === 'Escape') closeModal(); });

/* ---------- barcode ---------- */
function latestTerm(no) { const t = termsOf(no); return t[t.length - 1]; }
function doScan() {
  if (session && (session.role === 'student' || session.role === 'finance' || session.role === 'jshs')) return;
  const code = $('barcode').value.trim();
  const out = $('scanResult');
  if (!code) { out.innerHTML = '<div class="miss">The barcode box is empty. Click it, then scan the student ID.</div>'; return; }
  const s = student(code) || db.students.find(x => x.id.toLowerCase() === code.toLowerCase());
  if (!s) {
    out.innerHTML = '<div class="miss">No student found for <b>' + esc(code) + '</b>. Check the ID or use Add Student.</div>';
  } else {
    const t = latestTerm(s.id) || {};
    out.innerHTML = '<div class="hit">' +
      kv('Full name', s.name) + kv('Student ID no.', s.id) + kv('Section', t.section || '-') + kv('Grade level', t.level || '-') +
      '<div class="go"><button class="btn primary" type="button" id="scanView">View grades</button></div></div>';
    $('scanView').addEventListener('click', () => { $('sn').value = s.id; doSearch(); });
  }
  $('barcode').value = '';
  $('barcode').focus();
}
const kv = (k, v) => '<div class="kv"><span>' + esc(k) + '</span><b>' + esc(v) + '</b></div>';
$('btnScan').addEventListener('click', doScan);
$('barcode').addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); doScan(); } }); // scanners send Enter after the code

/* ---------- search ---------- */
let lastResults = [];
function filterTerms() {
  const crs = ($('crs').value || '').trim().toLowerCase();
  const q = $('sn').value.trim().toLowerCase(), sy = $('sy').value, sem = $('sem').value, lvl = $('lvl').value;
  return db.terms.filter(t => {
    const s = student(t.studentNo) || {};
    if (session && session.role === 'student') { if (t.studentNo !== session.studentNo) return false; }
    else if (q && !(t.studentNo.toLowerCase().includes(q) || (s.name || '').toLowerCase().includes(q))) return false;
    if (crs && !(s.course || '').toLowerCase().includes(crs)) return false;
    if (sy && t.sy !== sy) return false;
    if (sem && t.sem !== sem) return false;
    if (lvl && t.level !== lvl) return false;
    return true;
  }).sort((a, b) => a.studentNo.localeCompare(b.studentNo) || termSort(a, b));
}
function doSearch() {
  if (session && session.role === 'jshs') return;
  populateCourses();
  lastResults = filterTerms();
  renderResults();
}
function renderResults() {
  const box = $('results');
  lastResults = lastResults.filter(t => db.terms.includes(t) || db.terms.some(x => x.tid === t.tid))
    .map(t => db.terms.find(x => x.tid === t.tid));
  if (!lastResults.length) {
    box.innerHTML = '<p class="empty-state">No grade records match. Change the filters, or use Add Student to create one.</p>';
    return;
  }
  if (session && session.role === 'finance') { box.innerHTML = financeHtml(); return; }
  box.innerHTML = '<p class="count">' + lastResults.length + ' record' + (lastResults.length > 1 ? 's' : '') + ' found</p>' + lastResults.map(termCard).join('');
}
function termCard(t) {
  const s = student(t.studentNo) || { name: '(unknown)', course: '' };
  const rows = t.subjects.map((x, i) =>
    '<tr><td class="c">' + (i + 1) + '</td><td>' + esc(x.code) + '</td><td>' + esc(x.desc) + '</td><td class="c">' + esc(x.units) +
    '</td><td class="c">' + esc(x.grade) + '</td><td class="' + remarkClass(x.grade) + '">' + esc(remark(x.grade)) + '</td></tr>').join('') ||
    '<tr><td colspan="6" class="empty">No subjects yet. Click Add Subjects.</td></tr>';
  const g = gwa(t.subjects);
  return '<article class="term" data-tid="' + t.tid + '">' +
    '<div class="term-head"><div class="name">' + esc(s.name) + '</div>' +
    kv('Student no.', t.studentNo) + kv('Course', s.course || '-') + kv('Section', t.section || '-') +
    kv('School year', t.sy) + kv('Semester', t.sem) + kv('Grade level', t.level) + payKv(t) + '</div>' +
    '<div class="tbl-wrap"><table><thead><tr><th class="c">#</th><th>Code</th><th>Subject</th><th class="c">Units</th><th class="c">Grade</th><th>Remarks</th></tr></thead><tbody>' + rows + '</tbody>' +
    (t.subjects.length ? '<tfoot><tr><td colspan="3">Total units / General weighted average</td><td class="c">' + totalUnits(t.subjects) + '</td><td class="c">' + esc(g || '-') + '</td><td></td></tr></tfoot>' : '') +
    '</table></div>' +
    termActions() + '</article>';
}
function termActions() {
  if (isReg()) {
    return '<div class="term-actions">' +
      '<button class="btn small" data-act="subjects">Add Subjects</button>' +
      '<button class="btn small" data-act="grades">Input Grade</button>' +
      '<button class="btn small" data-act="edit">Edit</button>' +
      '<button class="btn small" data-act="print">Print</button>' +
      '<button class="btn small" data-act="doc">Generate Grades</button>' +
      '<button class="btn small" data-act="tor">Transcript of Records</button>' +
      (session.role === 'admin' ? '<button class="btn small" data-act="payment">Payment record</button>' : '') + '<button class="btn small danger" data-act="delete">Delete</button></div>';
  }
  if (session && session.role === 'faculty') {
    return '<div class="term-actions"><button class="btn small primary" data-act="fgrade">Input Grade</button></div>';
  }
  return ''; // students: view only
}
$('results').addEventListener('click', e => {
  const b = e.target.closest('button[data-act]');
  if (!b || !session) return;
  const t = db.terms.find(x => x.tid === b.closest('.term').dataset.tid);
  if (!t) return;
  const R = isReg(), F = session.role === 'faculty';
  const map = {
    subjects: () => R && addSubjects(t), grades: () => R && inputGrades(t), edit: () => R && editRecord(t),
    print: () => R && openDoc('Copy of Grades', gradesBody([t]), 'grades-' + t.studentNo, true),
    doc: () => R && openDoc('Copy of Grades', gradesBody([t]), 'grades-' + t.studentNo),
    tor: () => R && openDoc('Transcript of Records', torBody(student(t.studentNo)), 'TOR-' + t.studentNo),
    delete: () => R && deleteRecord(t),
    payment: () => isAdmin() && openLedger(t),
    fgrade: () => F && gradeEntry(t.subjects.map((x, i) => ({ t, i })), 'Input Grade: ' + (student(t.studentNo) || {}).name + ' (' + t.sy + ', ' + t.sem + ')', 'grades-' + t.studentNo)
  };
  if (map[b.dataset.act]) map[b.dataset.act]();
});
$('btnSearch').addEventListener('click', doSearch);
['sn', 'sy', 'sem', 'lvl'].forEach(id => $(id).addEventListener(id === 'sn' ? 'keydown' : 'change', e => { if (id !== 'sn' || e.key === 'Enter') doSearch(); }));

/* ---------- add student ---------- */
$('btnAddStudent').addEventListener('click', () => {
  if (!isReg()) return;
  openModal('Add Student',
    '<form id="fStudent" class="form-grid">' +
    '<div class="full"><label for="a_name">Full name</label><input id="a_name" required placeholder="Last name, First name Middle name"></div>' +
    '<div><label for="a_no">Student no.</label><input id="a_no" required></div>' +
    '<div><label for="a_sec">Section</label><input id="a_sec" required></div>' +
    '<div class="full"><label for="a_course">Course</label><input id="a_course" required></div>' +
    '<div><label for="a_sy">School year</label><select id="a_sy">' + opts(SYS) + '</select></div>' +
    '<div><label for="a_sem">Semester</label><select id="a_sem">' + opts(SEMS) + '</select></div>' +
    '<div><label for="a_lvl">Grade level</label><select id="a_lvl">' + opts(LEVELS) + '</select></div>' +
    '<div><label for="a_grad">Year graduated (optional)</label><input id="a_grad" placeholder="e.g. 2028"></div>' +
    '<p class="note full">If the student number already exists, a new school year / semester record is added to that student.</p>' +
    '<div class="modal-actions full"><button type="button" class="btn" id="mCancel">Cancel</button><button class="btn primary" type="submit">Save student</button></div></form>');
  $('mCancel').onclick = closeModal;
  $('fStudent').onsubmit = e => {
    e.preventDefault();
    const no = $('a_no').value.trim();
    let s = student(no);
    if (s) {
      s.name = $('a_name').value.trim(); s.course = $('a_course').value.trim();
      if ($('a_grad').value.trim()) s.yearGraduated = $('a_grad').value.trim();
    } else {
      s = { id: no, name: $('a_name').value.trim(), course: $('a_course').value.trim(), yearGraduated: $('a_grad').value.trim() };
      db.students.push(s);
    }
    const dupe = db.terms.find(t => t.studentNo === no && t.sy === $('a_sy').value && t.sem === $('a_sem').value);
    if (dupe) { alert('This student already has a record for ' + dupe.sy + ', ' + dupe.sem + '. Use Edit on that record.'); return; }
    const t = { tid: 't' + Date.now(), studentNo: no, sy: $('a_sy').value, sem: $('a_sem').value, level: $('a_lvl').value, section: $('a_sec').value.trim(), subjects: [] };
    db.terms.push(t);
    save();
    closeModal();
    $('sn').value = no; $('sy').value = ''; $('sem').value = ''; $('lvl').value = '';
    doSearch();
    addSubjects(t);
  };
});

/* ---------- add subjects ---------- */
function subjRow(s) {
  s = s || {};
  return '<tr><td><input class="r_code" value="' + esc(s.code) + '" placeholder="Code"></td>' +
    '<td><input class="r_desc" value="' + esc(s.desc) + '" placeholder="Subject description"></td>' +
    '<td><input class="r_units" type="number" min="0" step="0.5" value="' + esc(s.units) + '" style="width:80px"></td>' +
    '<td><button type="button" class="btn small danger r_del">Remove</button></td></tr>';
}
function bindRowDelete(root) {
  root.addEventListener('click', e => { if (e.target.classList.contains('r_del')) e.target.closest('tr').remove(); });
}
function addSubjects(t) {
  if (!isReg()) return;
  const s = student(t.studentNo);
  openModal('Add Subjects: ' + s.name + ' (' + t.sy + ', ' + t.sem + ')',
    '<p class="note">' + t.subjects.length + ' subject(s) already saved. Rows below are added to them.</p>' +
    '<table><thead><tr><th>Code</th><th>Subject</th><th>Units</th><th></th></tr></thead><tbody id="rows">' + subjRow() + subjRow() + subjRow() + '</tbody></table>' +
    '<div class="modal-actions"><button type="button" class="btn" id="addRow">Add row</button><button type="button" class="btn" id="mCancel">Cancel</button><button type="button" class="btn primary" id="mSave">Save subjects</button></div>', true);
  bindRowDelete($('rows'));
  $('addRow').onclick = () => $('rows').insertAdjacentHTML('beforeend', subjRow());
  $('mCancel').onclick = closeModal;
  $('mSave').onclick = () => {
    const added = [];
    $('rows').querySelectorAll('tr').forEach(tr => {
      const code = tr.querySelector('.r_code').value.trim(), desc = tr.querySelector('.r_desc').value.trim();
      if (code || desc) added.push({ code, desc, units: parseFloat(tr.querySelector('.r_units').value) || 0, grade: '' });
    });
    if (!added.length) { alert('Enter at least one subject.'); return; }
    t.subjects = t.subjects.concat(added);
    save(); closeModal(); renderResults();
  };
}

/* ---------- input grades ---------- */
function inputGrades(t) {
  if (!isReg()) return;
  const s = student(t.studentNo);
  if (!t.subjects.length) { alert('Add subjects first, then input grades.'); return addSubjects(t); }
  openModal('Input Grade: ' + s.name + ' (' + t.sy + ', ' + t.sem + ')',
    '<table><thead><tr><th>Code</th><th>Subject</th><th class="c">Units</th><th>Grade</th></tr></thead><tbody id="grows">' +
    t.subjects.map((x, i) => '<tr data-i="' + i + '"><td>' + esc(x.code) + '</td><td>' + esc(x.desc) + '</td><td class="c">' + esc(x.units) +
      '</td><td><input class="g_in" value="' + esc(x.grade) + '" style="width:90px" placeholder="1.00-5.00"></td></tr>').join('') + '</tbody></table>' +
    '<p class="note">Enter 1.00 to 5.00, or INC, DRP, W, UD. 3.00 and below is Passed; 5.00 is Failed.</p>' +
    '<div class="modal-actions"><button type="button" class="btn" id="mCancel">Cancel</button>' +
    '<button type="button" class="btn" id="gPrint">Save and print</button><button type="button" class="btn" id="gDoc">Save and generate document</button>' +
    '<button type="button" class="btn primary" id="mSave">Save grades</button></div>', true);
  const commit = () => {
    $('grows').querySelectorAll('tr').forEach(tr => { t.subjects[+tr.dataset.i].grade = normGrade(tr.querySelector('.g_in').value); });
    save(); closeModal(); renderResults();
  };
  $('mCancel').onclick = closeModal;
  $('mSave').onclick = commit;
  $('gPrint').onclick = () => { commit(); openDoc('Copy of Grades', gradesBody([t]), 'grades-' + t.studentNo, true); };
  $('gDoc').onclick = () => { commit(); openDoc('Copy of Grades', gradesBody([t]), 'grades-' + t.studentNo); };
}

/* ---------- edit record ---------- */
function editRecord(t) {
  if (!isReg()) return;
  const s = student(t.studentNo);
  openModal('Edit Student Record',
    '<div class="form-grid">' +
    '<div class="full"><label for="e_name">Full name</label><input id="e_name" value="' + esc(s.name) + '"></div>' +
    '<div><label for="e_no">Student no.</label><input id="e_no" value="' + esc(s.id) + '"></div>' +
    '<div><label for="e_grad">Year graduated</label><input id="e_grad" value="' + esc(s.yearGraduated) + '"></div>' +
    '<div class="full"><label for="e_course">Course</label><input id="e_course" value="' + esc(s.course) + '"></div>' +
    '<div><label for="e_sec">Section</label><input id="e_sec" value="' + esc(t.section) + '"></div>' +
    '<div><label for="e_lvl">Grade level</label><select id="e_lvl">' + opts(LEVELS, t.level) + '</select></div>' +
    '<div><label for="e_sy">School year</label><select id="e_sy">' + opts(SYS, t.sy) + '</select></div>' +
    '<div><label for="e_sem">Semester</label><select id="e_sem">' + opts(SEMS, t.sem) + '</select></div></div>' +
    '<h4>Subjects and grades</h4>' +
    '<table><thead><tr><th>Code</th><th>Subject</th><th>Units</th><th>Grade</th><th></th></tr></thead><tbody id="erows">' +
    t.subjects.map(x => '<tr><td><input class="r_code" value="' + esc(x.code) + '"></td><td><input class="r_desc" value="' + esc(x.desc) + '"></td>' +
      '<td><input class="r_units" type="number" min="0" step="0.5" value="' + esc(x.units) + '" style="width:80px"></td>' +
      '<td><input class="r_grade" value="' + esc(x.grade) + '" style="width:90px"></td>' +
      '<td><button type="button" class="btn small danger r_del">Remove</button></td></tr>').join('') + '</tbody></table>' +
    '<div class="modal-actions"><button type="button" class="btn" id="mCancel">Cancel</button><button type="button" class="btn primary" id="mSave">Save changes</button></div>', true);
  bindRowDelete($('erows'));
  $('mCancel').onclick = closeModal;
  $('mSave').onclick = () => {
    const newNo = $('e_no').value.trim();
    if (!newNo || !$('e_name').value.trim()) { alert('Full name and student no. are required.'); return; }
    if (newNo !== s.id && student(newNo)) { alert('Student no. ' + newNo + ' already belongs to another student.'); return; }
    if (db.terms.some(x => x !== t && x.studentNo === s.id && x.sy === $('e_sy').value && x.sem === $('e_sem').value)) {
      alert('This student already has a record for that school year and semester.'); return;
    }
    if (newNo !== s.id) { db.terms.forEach(x => { if (x.studentNo === s.id) x.studentNo = newNo; }); s.id = newNo; }
    s.name = $('e_name').value.trim(); s.course = $('e_course').value.trim(); s.yearGraduated = $('e_grad').value.trim();
    t.section = $('e_sec').value.trim(); t.level = $('e_lvl').value; t.sy = $('e_sy').value; t.sem = $('e_sem').value;
    t.subjects = [];
    $('erows').querySelectorAll('tr').forEach(tr => {
      const code = tr.querySelector('.r_code').value.trim(), desc = tr.querySelector('.r_desc').value.trim();
      if (code || desc) t.subjects.push({ code, desc, units: parseFloat(tr.querySelector('.r_units').value) || 0, grade: normGrade(tr.querySelector('.r_grade').value) });
    });
    save(); closeModal(); renderResults();
  };
}

/* ---------- delete (admin password required) ---------- */
function deleteRecord(t) {
  if (!isReg()) return;
  const s = student(t.studentNo);
  openModal('Delete records',
    '<p>Delete records for <b>' + esc(s.name) + '</b> (' + esc(t.studentNo) + ')?</p>' +
    '<label class="radio"><input type="radio" name="dscope" value="term" checked> This record only: ' + esc(t.sy) + ', ' + esc(t.sem) + '</label>' +
    '<label class="radio"><input type="radio" name="dscope" value="all"> The whole student: profile and every semester</label>' +
    '<label for="d_pass" style="margin-top:.8rem">Your password</label><input id="d_pass" type="password">' +
    '<p id="dErr" class="err" role="alert"></p>' +
    '<div class="modal-actions"><button type="button" class="btn" id="mCancel">Cancel</button><button type="button" class="btn danger solid" id="mDel">Delete</button></div>');
  $('mCancel').onclick = closeModal;
  const go = async () => {
    if (!(await verifyCurrentPassword($('d_pass').value))) { $('dErr').textContent = 'Incorrect password. Nothing was deleted.'; return; }
    const all = document.querySelector('input[name="dscope"]:checked').value === 'all';
    if (all) {
      db.terms = db.terms.filter(x => x.studentNo !== s.id);
      db.students = db.students.filter(x => x.id !== s.id);
    } else {
      db.terms = db.terms.filter(x => x !== t);
      if (!db.terms.some(x => x.studentNo === s.id)) db.students = db.students.filter(x => x.id !== s.id);
    }
    save(); closeModal(); doSearch();
  };
  $('mDel').onclick = go;
  $('d_pass').addEventListener('keydown', e => { if (e.key === 'Enter') go(); });
}

