  '.sig{margin-top:40px;display:flex;justify-content:space-between;font-size:13px}.sig div{width:44%;text-align:center;border-top:1px solid #000;padding-top:3px}.sig.s3 div{width:30%}' +
  '.fine{font-size:11px;margin-top:14px}.r{text-align:right!important}' +
  '@media print{.bar{display:none}body{padding:0}.pb:last-child{page-break-after:auto}}';

function docHeader(title, registrar) {
  return '<div class="hd"><img src="' + LOGO + '" alt="WCCAS seal"><div class="sc">' + esc(SCHOOL) + '</div>' +
    (registrar === 'finance' ? '<div class="of">Finance Office</div>' : registrar ? '<div class="of">Office of the Registrar</div>' : '<div class="of">Lubao, Pampanga</div>') +
    '<div class="tt">' + esc(title) + '</div></div>';
}
function subjTable(subjects) {
  const rows = subjects.map(s => '<tr><td>' + esc(s.code) + '</td><td>' + esc(s.desc) + '</td><td class="c">' + esc(s.grade) + '</td><td class="c">' + esc(s.units) + '</td><td>' + esc(remark(s.grade)) + '</td></tr>').join('') ||
    '<tr><td colspan="5" class="c">No subjects recorded</td></tr>';
  return '<table class="g"><thead><tr><th>Code</th><th>Subject</th><th class="c">Grade</th><th class="c">Units</th><th>Remarks</th></tr></thead><tbody>' + rows + '</tbody></table>';
}
function registrarName(kind) {
  const n = (db.settings && db.settings.registrarNames) || {};
  return (kind === 'jshs' ? n.jshs : n.college) || '';
}
function sigBlock(left, name) {
  return '<div class="sig"><div>' + esc(left) + '</div><div>' + (name ? '<b>' + esc(name) + '</b><br>' : '') + 'Registrar</div></div>';
}
const financeName = () => (db.settings && db.settings.financeOfficer) || '';
function sigBlock3(left, fin, reg) {
  return '<div class="sig s3"><div>' + esc(left) + '</div><div>' + (fin ? '<b>' + esc(fin) + '</b><br>' : '') + 'Finance Officer</div><div>' + (reg ? '<b>' + esc(reg) + '</b><br>' : '') + 'Registrar</div></div>';
}
function financeSig() {
  const fin = financeName();
  return '<div class="sig"><div>' + (fin ? '<b>' + esc(fin) + '</b><br>' : '') + 'Prepared by (Finance Officer)</div><div>Noted by (Registrar)</div></div>';
}
function stamp() { return new Date().toLocaleString('en-PH', { dateStyle: 'long', timeStyle: 'short' }); }

function gradesBody(terms) {
  // one page per student
  const byStudent = {};
  terms.forEach(t => { (byStudent[t.studentNo] = byStudent[t.studentNo] || []).push(t); });
  return Object.keys(byStudent).map(no => {
    const s = student(no) || { name: no, course: '' };
    const list = byStudent[no].sort(termSort);
    return '<div class="page pb">' + docHeader('COPY OF GRADES', true) +
      '<table class="info"><tr><td><b>Name:</b> ' + esc(s.name) + '</td><td><b>Student No.:</b> ' + esc(no) + '</td></tr>' +
      '<tr><td colspan="2"><b>Course:</b> ' + esc(s.course) + '</td></tr></table>' +
      list.map(t => '<div class="sem">' + esc(t.sy) + ' &mdash; ' + esc(t.sem) + ' &mdash; ' + esc(t.level) + ' &mdash; Section ' + esc(t.section) + '</div>' + subjTable(t.subjects) +
        '<div style="font-size:13px;text-align:right">Total units: <b>' + totalUnits(t.subjects) + '</b> &nbsp; General weighted average: <b>' + esc(gwa(t.subjects) || '-') + '</b></div>').join('') +
      '<div class="fine">Grading: 1.00 (highest) to 3.00 (lowest passing); 5.00 Failed; INC Incomplete; DRP Dropped. Printed ' + esc(stamp()) + '.</div>' +
      sigBlock('Prepared by', registrarName('college')) + '</div>';
  }).join('');
}

function torBody(s) {
  if (!s) return '<p>Student not found.</p>';
  const list = termsOf(s.id);
  const blocks = list.map(t =>
    '<div class="sem">' + esc(t.sem) + ', ' + esc(t.sy) + ' &mdash; ' + esc(t.level) + ' (' + esc(t.section) + ')</div>' + subjTable(t.subjects) +
    '<div style="font-size:12px;text-align:right">Total units: <b>' + totalUnits(t.subjects) + '</b> &nbsp; GWA: <b>' + esc(gwa(t.subjects) || '-') + '</b></div>').join('') ||
    '<p>No grades recorded.</p>';
  return '<div class="page">' + docHeader('OFFICIAL TRANSCRIPT OF RECORDS', true) +
    '<table class="info"><tr><td><b>Full Name:</b> ' + esc(s.name) + '</td><td><b>Student Number:</b> ' + esc(s.id) + '</td></tr>' +
    '<tr><td><b>Course:</b> ' + esc(s.course) + '</td><td><b>Year Graduated:</b> ' + esc(s.yearGraduated || '') + '</td></tr></table>' +
    blocks +
    '<div class="fine">Grading: 1.00 (highest) to 3.00 (lowest passing); 5.00 Failed; INC Incomplete; DRP Dropped. Date issued: ' + esc(stamp()) + '. Not valid without the school seal.</div>' +
    sigBlock('Prepared by', registrarName('college')) + '</div>';
}

function subjectBody(code, desc, terms) {
  const rows = terms.map(t => ({ t, s: student(t.studentNo) || { name: t.studentNo }, sub: t.subjects.find(x => x.code === code && x.desc === desc) }))
    .filter(r => r.sub).sort((a, b) => (a.s.name || '').localeCompare(b.s.name || ''));
  return '<div class="page">' + docHeader('GRADES PER SUBJECT', true) +
    '<table class="info"><tr><td><b>Subject:</b> ' + esc(code) + ' &mdash; ' + esc(desc) + '</td></tr>' +
    '<tr><td><b>Filters:</b> ' + esc([$('sy').value, $('sem').value, $('lvl').value].filter(Boolean).join(' | ') || 'All records') + '</td></tr></table>' +
    '<table class="g"><thead><tr><th class="c">#</th><th>Student no.</th><th>Name</th><th>Section</th><th>School year / Semester</th><th class="c">Grade</th><th>Remarks</th></tr></thead><tbody>' +
    rows.map((r, i) => '<tr><td class="c">' + (i + 1) + '</td><td>' + esc(r.t.studentNo) + '</td><td>' + esc(r.s.name) + '</td><td>' + esc(r.t.section) + '</td><td>' + esc(r.t.sy) + ', ' + esc(r.t.sem) +
      '</td><td class="c">' + esc(r.sub.grade) + '</td><td>' + esc(remark(r.sub.grade)) + '</td></tr>').join('') + '</tbody></table>' +
    '<div class="fine">Printed ' + esc(stamp()) + '.</div>' + sigBlock('Instructor', registrarName('college')) + '</div>';
}

const DOC_REG = {};
function openDoc(title, body, fname, autoPrint) {
  if (!isReg() && !isFin() && !isJshs()) return;
  fname = String(fname).replace(/[^A-Za-z0-9_-]/g, '_');
  const id = 'd' + Date.now() + Math.floor(Math.random() * 1000);
  DOC_REG[id] = { title, body, fname };
  const html = '<!DOCTYPE html><html><head><meta charset="utf-8"><title>' + esc(title) + '</title><style>' + DOC_CSS + '</style></head><body>' +
    '<div class="bar"><button onclick="window.print()">Print</button><button onclick="sv(\'doc\')">Save as Word Document</button>' +
    '<button onclick="sv(\'xlsx\')">Save as Spreadsheet (.xlsx)</button><button onclick="sv(\'db\')">Save as Database (Access)</button><button onclick="window.close()">Close</button></div>' +
    '<div id="doc">' + body + '</div>' +
    '<script>function sv(k){var o=window.opener;if(!o||o.closed||!o.wccasSave){alert("Go back to the WCCAS page, then try again.");return;}o.wccasSave(k,"' + id + '");}' +
    (autoPrint ? 'window.onload=function(){setTimeout(function(){window.print()},400)};' : '') +
    '<\/script></body></html>';
  const w = window.open('', '_blank');
  if (!w) { alert('The document window was blocked. Allow pop-ups for this page and try again.'); return; }
  w.document.open(); w.document.write(html); w.document.close();
}

