/* ---------- save any generated report as Word / Spreadsheet / Database ---------- */
const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', mdash: '\u2014', ndash: '\u2013', rsquo: '\u2019', lsquo: '\u2018', ldquo: '\u201c', rdquo: '\u201d' };
const decodeEnt = t => t.replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n)).replace(/&#x([0-9a-f]+);/gi, (m, n) => String.fromCharCode(parseInt(n, 16)))
  .replace(/&([a-z]+);/gi, (m, n) => (ENT[n.toLowerCase()] !== undefined ? ENT[n.toLowerCase()] : m));
const plain = h => decodeEnt(h.replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]*>/g, '')).replace(/\s+/g, ' ').trim();
function cellsOf(tr) {
  const out = [], re = /<t[dh]\b([^>]*)>([\s\S]*?)<\/t[dh]>/g;
  let m;
  while ((m = re.exec(tr))) {
    out.push(plain(m[2]));
    const cs = /colspan="(\d+)"/.exec(m[1]);
    if (cs) for (let i = 1; i < +cs[1]; i++) out.push('');
  }
  return out;
}
function rowsOf(html) {
  const out = [], re = /<tr\b[^>]*>([\s\S]*?)<\/tr>/g;
  let m;
  while ((m = re.exec(html))) out.push(cellsOf(m[1]));
  return out;
}
// Reads the header lines and tables out of a generated document so it can be saved as a spreadsheet or database.
function parseDoc(body) {
  const lines = [];
  ['sc', 'of', 'tt'].forEach(c => { const m = new RegExp('class="' + c + '">(.*?)</div>').exec(body); if (m && plain(m[1])) lines.push(plain(m[1])); });
  const tables = [];
  let label = '';
  const re = /<div class="sem">([\s\S]*?)<\/div>|<table\b([^>]*)>([\s\S]*?)<\/table>/g;
  let m;
  while ((m = re.exec(body))) {
    if (m[1] !== undefined) { label = plain(m[1]); continue; }
    const inner = m[3];
    if (/class="info"/.test(m[2])) {
      const pairs = [];
      rowsOf(inner).forEach(r => {
        for (let i = 0; i < r.length; i++) {
          const c = r[i];
          if (/:$/.test(c) && i + 1 < r.length) { pairs.push([c.replace(/:$/, ''), r[i + 1]]); i++; }
          else { const k = c.indexOf(':'); if (k > 0) pairs.push([c.slice(0, k).trim(), c.slice(k + 1).trim()]); }
        }
      });
      tables.push({ name: 'Details', headers: ['Field', 'Value'], rows: pairs });
      continue;
    }
    const head = /<thead>([\s\S]*?)<\/thead>/.exec(inner);
    const headers = head ? (rowsOf(head[1])[0] || []) : [];
    const rest = rowsOf(inner.replace(/<thead>[\s\S]*?<\/thead>/, ''));
    const n = headers.length || (rest[0] || []).length;
    const rows = rest.map(r => { const x = r.slice(0, n); while (x.length < n) x.push(''); return x; });
    tables.push({ name: label || 'Table ' + (tables.length + 1), headers: headers.length ? headers : rows.shift(), rows });
  }
  return { lines, tables };
}
const moneyNum = t => (/^\u20b1[\d,]+(\.\d+)?$/.test(t) ? parseFloat(t.replace(/[\u20b1,]/g, '')) : null);
function docSheet(d) {
  const rows = d.lines.map((l, i) => [{ v: l, s: i === 0 || i === d.lines.length - 1 ? 1 : 0 }]);
  let cols = 1;
  d.tables.forEach(t => {
    rows.push([]);
    if (t.name !== 'Details') rows.push([{ v: t.name, s: 1 }]);
    rows.push(t.headers.map(h => ({ v: h, s: 1 })));
    t.rows.forEach(r => rows.push(r.map(c => { const n = moneyNum(c); return n === null ? { v: c } : { v: n, n: true, s: 2 }; })));
    cols = Math.max(cols, t.headers.length);
  });
  const widths = [];
  for (let c = 0; c < cols; c++) widths.push(Math.min(45, Math.max(12, ...rows.map(r => (r[c] && r[c].v != null ? String(r[c].v).length + 2 : 0)))));
  return { rows, widths };
}
// A zip with one CSV per table plus a script that builds the Access (.accdb) file from them.
function dbZip(d, fname) {
  fname = String(fname).replace(/[^A-Za-z0-9_-]/g, '_');
  const safeName = (x, i) => 'T' + i + '_' + (String(x).replace(/[^A-Za-z0-9 _-]/g, '').trim().replace(/\s+/g, '_').slice(0, 30) || 'Table');
  const safeCol = (x, seen) => {
    let c = String(x).replace(/[\[\]"'\r\n]/g, '').replace(/[^\x20-\x7E]/g, '').trim().slice(0, 60) || 'Column';
    let k = c, n = 2;
    while (seen[k.toLowerCase()]) k = c + n++;
    seen[k.toLowerCase()] = 1;
    return k;
  };
  const files = [], create = [], load = [];
  d.tables.forEach((t, i) => {
    const tname = safeName(t.name, i + 1), seen = {}, cols = t.headers.map(h => safeCol(h, seen));
    const data = t.rows.map(r => r.map(c => { const n = moneyNum(c); return n === null ? c : n.toFixed(2); }));
    const long = cols.map((c, ci) => data.some(r => String(r[ci] || '').length > 255));
    files.push({ name: fname + '_' + (i + 1) + '.csv', text: csvText(cols, data) });
    create.push('db.Execute "CREATE TABLE [' + tname + '] (' + cols.map((c, ci) => '[' + c + '] ' + (long[ci] ? 'LONGTEXT' : 'TEXT(255)')).join(', ') + ')"');
    load.push('app.DoCmd.TransferText 0, , "' + tname + '", folder & "\\' + fname + '_' + (i + 1) + '.csv", True');
  });
  const vbs = ["' Builds " + fname + ".accdb from the CSV files in this same folder.", "' Needs Windows with Microsoft Access installed. Double-click to run.",
    'Dim fso, app, folder, dbPath, db', 'Set fso = CreateObject("Scripting.FileSystemObject")', 'folder = fso.GetParentFolderName(WScript.ScriptFullName)',
    'dbPath = folder & "\\' + fname + '.accdb"', 'If fso.FileExists(dbPath) Then fso.DeleteFile dbPath, True', 'Set app = CreateObject("Access.Application")',
    'app.NewCurrentDatabase dbPath', 'Set db = app.CurrentDb'].concat(create, load, ['app.CloseCurrentDatabase', 'app.Quit', 'MsgBox "Done. Created " & dbPath, 64, "WCCAS"']).join('\r\n') + '\r\n';
  files.push({ name: fname + '_BuildAccessDB.vbs', text: vbs });
  files.push({ name: 'README.txt', text: 'Extract ALL files from this zip into one folder, then double-click ' + fname + '_BuildAccessDB.vbs on a Windows PC with Microsoft Access.\r\nIt creates ' + fname + '.accdb.\r\n' });
  return makeZip(files, 'application/zip');
}
function wordHtml(body) {
  return '<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word"><head><meta charset="utf-8"><style>' + DOC_CSS + '</style></head><body>' + body + '</body></html>';
}
function saveWord(body, fname) {
  fname = String(fname).replace(/[^A-Za-z0-9_-]/g, '_');
  saveText(fname + '.doc', '\ufeff' + wordHtml(body), 'application/msword');
}
// called from the generated-document window
window.wccasSave = (kind, id) => {
  const d = DOC_REG[id];
  if (!d || !session) return;
  if (kind === 'xlsx') { const sh = docSheet(parseDoc(d.body)); saveBlob(d.fname + '.xlsx', buildXlsx(sh.rows, sh.widths, 'Report')); }
  else if (kind === 'db') saveBlob(d.fname + '-Database.zip', dbZip(parseDoc(d.body), d.fname));
  else saveWord(d.body, d.fname);
};

/* ---------- School Administrator: Backup Data -> folder "All Back Up Files" ---------- */
function backupSheets() {
  const sheet = (name, headers, data, widths, money) => ({
    name, widths: widths || headers.map(h => Math.max(14, h.length + 2)),
    rows: [headers.map(h => ({ v: h, s: 1 }))].concat(data.map(r => r.map((v, ci) => (typeof v === 'number' ? { v, n: true, s: (money || []).indexOf(ci) >= 0 ? 2 : 0 } : { v: v == null ? '' : v }))))
  });
  const nm = no => (student(no) || {}).name || no, cr = no => (student(no) || {}).course || '';
  const grade = [], pay = [], ledger = [], enr = [], enrSub = [];
  db.terms.forEach(t => {
    const base = [t.studentNo, nm(t.studentNo), cr(t.studentNo), t.section, t.level, t.sy, t.sem];
    if (!t.subjects.length) grade.push(base.concat(['', '', '', '', '']));
    t.subjects.forEach(x => grade.push(base.concat([x.code, x.desc, parseFloat(x.units) || 0, x.grade, remark(x.grade)])));
    if (t.fees) {
      const p = payInfo(t);
      pay.push(base.concat([t.fees.registration, t.fees.tuition, t.fees.misc, t.fees.schoolId, p.total, p.paid, p.balance, p.status === 'paid' ? 'Fully Paid' : (p.status === 'balance' ? 'With Outstanding Balance' : '')]));
      (t.fees.payments || []).forEach(x => { if (x.amount !== '' && x.amount != null) ledger.push([t.studentNo, nm(t.studentNo), t.sy, t.sem, x.label, x.date, x.or, x.amount]); });
    }
  });
  db.enrollments.forEach(e => {
    enr.push([DIVISIONS[e.division].label, e.idNo, e.name, e.level, e.track || '', e.cluster || '', e.lastSchool, e.sy, e.birthday, e.age, e.gender, e.contact, fmtDateTime(new Date(e.enrolledAt)), e.studentType, (e.requirements || []).join('; ')]);
    (e.subjects || []).forEach(x => enrSub.push([e.idNo, e.name, e.sy, x.code, x.desc, x.units]));
  });
  const names = (db.settings && db.settings.registrarNames) || {};
  return [
    sheet('Students', ['Student No.', 'Full Name', 'Course', 'Year Graduated'], db.students.map(s => [s.id, s.name, s.course, s.yearGraduated || '']), [16, 32, 44, 16]),
    sheet('Grade Records', ['Student No.', 'Full Name', 'Course', 'Section', 'Year Level', 'School Year', 'Semester', 'Subject Code', 'Subject', 'Units', 'Grade', 'Remarks'], grade, [16, 28, 36, 12, 20, 16, 18, 14, 34, 8, 8, 14]),
    sheet('Payments', ['Student No.', 'Full Name', 'Course', 'Section', 'Year Level', 'School Year', 'Semester', 'Registration', 'Tuition Fee', 'Misc Fee', 'School ID', 'Total Fees', 'Total Paid', 'Balance', 'Status'], pay, null, [7, 8, 9, 10, 11, 12, 13]),
    sheet('Payment Ledger', ['Student No.', 'Full Name', 'School Year', 'Semester', 'Payment', 'Date', 'Receipt (OR)', 'Amount'], ledger, null, [7]),
    sheet('Enrollments', ['Division', 'LRN / Student No.', 'Full Name', 'Level', 'Track', 'Cluster', 'Last School', 'School Year', 'Birthday', 'Age', 'Gender', 'Contact', 'Enrollment Date', 'Student Type', 'Requirements'], enr, [20, 18, 30, 20, 16, 30, 28, 16, 12, 6, 10, 16, 30, 14, 60]),
    sheet('Enrollment Subjects', ['Student No.', 'Full Name', 'School Year', 'Subject Code', 'Subject Description', 'Unit'], enrSub),
    sheet('Accounts', ['Username', 'Role', 'Student No.', 'Created'],
      Object.keys(FIXED).map(r => [FIXED[r].user, FIXED[r].label, '', '']).concat(db.accounts.map(a => [a.user, ROLE_LABEL[a.role], a.studentNo || '', (a.created || '').slice(0, 10)])), [26, 22, 16, 14]),
    sheet('Names', ['Position', 'Name'], [['College Registrar', names.college || ''], ['JSHS Registrar', names.jshs || ''], ['Finance Officer', financeName()]], [22, 34])
  ];
}
function backupDocs() {
  const br = '<div style="page-break-after:always"></div>';
  const none = '<p>No records.</p>';
  const payRows = db.terms.filter(t => t.fees).map(t => { const p = payInfo(t), s = student(t.studentNo) || {}; return '<tr><td>' + esc(t.studentNo) + '</td><td>' + esc(s.name) + '</td><td>' + esc(t.level) + '</td><td>' + esc(t.sy) + ', ' + esc(t.sem) +
    '</td><td class="r">' + peso(p.total) + '</td><td class="r">' + peso(p.paid) + '</td><td class="r">' + peso(p.balance) + '</td><td>' + (p.status === 'paid' ? 'Fully Paid' : 'With Outstanding Balance') + '</td></tr>'; }).join('');
  const accRows = Object.keys(FIXED).map(r => '<tr><td>' + esc(FIXED[r].user) + '</td><td>' + esc(FIXED[r].label) + '</td><td></td></tr>').concat(db.accounts.map(a => '<tr><td>' + esc(a.user) + '</td><td>' + esc(ROLE_LABEL[a.role]) + '</td><td>' + esc(a.studentNo || '') + '</td></tr>')).join('');
  return [
    ['Copy of Grades - All Students.doc', db.terms.length ? gradesBody(db.terms.slice()) : none],
    ['Transcript of Records - All Students.doc', db.students.length ? db.students.map(s => torBody(s)).join(br) : none],
    ['Enrollment Records.doc', db.enrollments.length ? db.enrollments.map(enrollBody).join(br) : none],
    ['Payment Records.doc', '<div class="page">' + docHeader('PAYMENT RECORDS', 'finance') + '<table class="g"><thead><tr><th>Student No.</th><th>Full Name</th><th>Year Level</th><th>School Year / Semester</th><th class="r">Total Fees</th><th class="r">Paid</th><th class="r">Balance</th><th>Status</th></tr></thead><tbody>' + (payRows || '<tr><td colspan="8">No payment records.</td></tr>') + '</tbody></table></div>'],
    ['User Accounts.doc', '<div class="page">' + docHeader('USER ACCOUNTS', true) + '<table class="g"><thead><tr><th>Username</th><th>Role</th><th>Student No.</th></tr></thead><tbody>' + accRows + '</tbody></table></div>']
  ];
}
async function buildBackupZip() {
  const root = 'All Back Up Files/', stampDay = new Date().toISOString().slice(0, 10);
  const xl = new Uint8Array(await buildWorkbook(backupSheets()).arrayBuffer());
  const files = [{ name: root + 'Spreadsheet/WCCAS-All-Data.xlsx', bytes: xl }];
  backupDocs().forEach(([n, body]) => files.push({ name: root + 'Documents/' + n, text: '\ufeff' + wordHtml(body) }));
  files.push({ name: root + 'Restore File/wccas-backup-' + stampDay + '.json', text: JSON.stringify(db, null, 2) });
  files.push({ name: root + 'README.txt', text: 'WCCAS Copy of Grades - backup made ' + stamp() + '\r\n\r\nSpreadsheet\\WCCAS-All-Data.xlsx   all data, one sheet per kind of record\r\nDocuments\\*.doc             Word documents\r\nRestore File\\*.json          use the Restore data button to bring everything back\r\n' });
  return makeZip(files, 'application/zip');
}

/* ---------- keep the person logged in on refresh (this tab only) ---------- */
(function restoreSession() {
  let sess = null;
  const raw = sessionStorage.getItem('wccas_auth');
  if (raw === '1') sess = null;
  else { try { sess = JSON.parse(raw); } catch (e) { sess = null; } }
  if (!sess || !sess.role) return;
  if (FIXED[sess.role] && sess.user !== FIXED[sess.role].user) return;
  if (!FIXED[sess.role] && !db.accounts.some(a => a.user === sess.user && a.role === sess.role)) return;
  startSession(sess);
})();
